class Solution {public:bool solve(int n,vector<vector<int>>edges){vector<int>p(n),size(n,1);vector<long long>offset(n);iota(p.begin(),p.end(),0);function<int(int)>find=[&](int u){if(p[u]!=u){int old=p[u];p[u]=find(old);offset[u]+=offset[old];}return p[u];};for(auto e:edges){int a=find(e[0]),b=find(e[1]);long long pu=offset[e[0]],pv=offset[e[1]],bridge=1LL*e[2]+pu-pv;if(a==b){if(pv-pu!=e[2])return false;}else if(size[a]>=size[b]){p[b]=a;offset[b]=bridge;size[a]+=size[b];}else{p[a]=b;offset[a]=-bridge;size[b]+=size[a];}}return true;}};